class Solution:
    def findThePrefixCommonArray(self, A: list[int], B: list[int]) -> list[int]:
        n = len(A)
        count = [0] * (n + 1)
        common = 0
        ans = []
        for x, y in zip(A, B):
            count[x] += 1
            if count[x] == 2:
                common += 1
            count[y] += 1
            if count[y] == 2:
                common += 1
            ans.append(common)
        return ans

class Solution {
public:
    std::vector<int> findThePrefixCommonArray(std::vector<int>& A, std::vector<int>& B) {
        int n = A.size();
        std::vector<int> count(n + 1, 0);
        std::vector<int> ans;
        int common = 0;
        for (int i = 0; i < n; i++) {
            count[A[i]]++;
            if (count[A[i]] == 2) common++;
            count[B[i]]++;
            if (count[B[i]] == 2) common++;
            ans.push_back(common);
        }
        return ans;
    }
};

class Solution {
    public int[] findThePrefixCommonArray(int[] A, int[] B) {
        int n = A.length;
        int[] count = new int[n + 1];
        int[] ans = new int[n];
        int common = 0;
        for (int i = 0; i < n; i++) {
            count[A[i]]++;
            if (count[A[i]] == 2) common++;
            count[B[i]]++;
            if (count[B[i]] == 2) common++;
            ans[i] = common;
        }
        return ans;
    }
}

var findThePrefixCommonArray = function(A, B) {
    const n = A.length;
    const count = new Array(n + 1).fill(0);
    const ans = [];
    let common = 0;
    for (let i = 0; i < n; i++) {
        count[A[i]]++;
        if (count[A[i]] === 2) common++;
        count[B[i]]++;
        if (count[B[i]] === 2) common++;
        ans.push(common);
    }
    return ans;
};
